import itertools

def is_bad_triplet(x, y, z):
    if not (x < y + z and y < x + z and z < x + y):
        return False
    if (x + y + z) % 2 != 0:
        return False
    return True

def check_set(A):
    for triplet in itertools.combinations(A, 3):
        if is_bad_triplet(*triplet):
            return True
    return False

def find_max_size(N):
    import itertools
    max_size = 0
    for k in range(1, N + 1):
        found_k = False
        for A in itertools.combinations(range(1, N + 1), k):
            if not check_set(A):
                max_size = k
                found_k = True
                break
        if not found_k:
            break
    return max_size

for N in range(1, 21):
    print(f"N={N}, max_size={find_max_size(N)}")

