import itertools

def is_bad_triplet(x, y, z):
    if not (x < y + z and y < x + z and z < x + y):
        return False
    if (x + y + z) % 2 != 0:
        return False
    return True

def find_max_size_recursive(N):
    max_s = 0
    def solve(current_set, candidate_idx):
        nonlocal max_s
        if candidate_idx > N:
            max_s = max(max_s, len(current_set))
            return

        # Try adding candidate_idx
        can_add = True
        for i in range(len(current_set)):
            for j in range(i + 1, len(current_set)):
                if is_bad_triplet(current_set[i], current_set[j], candidate_idx):
                    can_add = False
                    break
            if not can_add: break

        if can_add:
            solve(current_set + [candidate_idx], candidate_idx + 1)

        # Try not adding candidate_idx
        # Pruning: if we don't add it, can we still beat max_s?
        if len(current_set) + (N - candidate_idx) > max_s:
            solve(current_set, candidate_idx + 1)

    solve([], 1)
    return max_s

for N in range(1, 21):
    print(f"N={N}, max_size={find_max_size_recursive(N)}")
